<script setup lang="ts">const route=useRoute(),{api}=useShopApi();const{data}=await useAsyncData('active-campaigns',()=>api<any[]>('/campaigns/active'));const now=ref(Date.now());let timer:any;onMounted(()=>timer=setInterval(()=>now.value=Date.now(),1000));onUnmounted(()=>clearInterval(timer));function remaining(end:string){const seconds=Math.max(0,Math.floor((new Date(end).getTime()-now.value)/1000)),d=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return `${d?d+' روز ':''}${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}</script>
<template><section v-if="route.path==='/'&&data?.length" class="mx-auto max-w-7xl space-y-8 px-4 py-10"><div v-for="campaign in data" :key="campaign.id" class="overflow-hidden rounded-3xl bg-gradient-to-l from-rose-700 to-orange-500 p-5 text-white md:p-8"><div class="mb-6 flex flex-wrap items-center justify-between gap-4"><div><span class="rounded-lg bg-white/20 px-3 py-1 text-xs font-bold">{{campaign.badge||'فروش ویژه'}}</span><h2 class="mt-3 text-2xl font-black">{{campaign.title}}</h2></div><div class="rounded-xl bg-slate-950/25 px-4 py-3 text-center"><p class="text-[10px] opacity-80">زمان باقی‌مانده</p><b dir="ltr" class="mt-1 block font-mono text-lg">{{remaining(campaign.ends_at)}}</b></div></div><div class="grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-6"><ProductCard v-for="p in campaign.products" :key="p.id" :product="p"/></div></div></section></template>
